using Astrea.BattleActions;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "DiceTargetCastState", menuName = "Data/Battle/Game States/Dice Target Cast State")]
public class DiceTargetCastState : GameState
{
	[Header("Action Instance Reference")]
	[SerializeField]
	private ActionInstanceReference actionInstanceReference;

	public void ActionCasted()
	{
		ActionInstance value = actionInstanceReference.Value;
		GameObject actionOwner = value.ActionOwner;
		ChooseDiceAction chooseDiceAction = value.ActionFace.BattleAction as ChooseDiceAction;
		ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(value);
		if (value is DiceInstance)
		{
			SetPlayerDiceAsJustPlayed(value as DiceInstance);
		}
		ReferenceSingleton<BattleHandler>.Instance.BeforeActionCasted();
		if (chooseDiceAction.OverrideDiceToSelectAmount)
		{
			chooseDiceAction.CastAmount(value.ActionFace.ModifiedActionValue, actionOwner);
		}
		else
		{
			chooseDiceAction.Cast(actionOwner);
		}
		if (value.ActionFace.EnableSecondAction)
		{
			value.ActionFace.SecondBattleAction.DiceSecondActionLogic.OnDrop(value.ActionFace, null, actionOwner);
		}
		ReferenceSingleton<BattleHandler>.Instance.ActionCasted();
	}

	private void SetPlayerDiceAsJustPlayed(DiceInstance diceInstance)
	{
		if (diceInstance.DiceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			(diceInstance.OriginalDice as PlayerDice).DiceJustPlayed = true;
		}
	}
}
